// ─── Animations ───────────────────────────────────────────────────────────────

const fadeIn   = keyframes`from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); }`;
const shakeAnim = keyframes`0%,100%{ transform: translateX(0); } 25%{ transform: translateX(-10px); } 75%{ transform: translateX(10px); }`;
const pop      = keyframes`0%{ transform: scale(1); } 50%{ transform: scale(1.2); } 100%{ transform: scale(1); }`;
const flyUp    = keyframes`from{ transform: translateY(0) scale(1); opacity: 1; } to{ transform: translateY(-120px) scale(0.3) rotate(360deg); opacity: 0; }`;
const bounce   = keyframes`0%,100%{ transform: translateY(0); } 50%{ transform: translateY(-12px); }`;

