// ─── Component ────────────────────────────────────────────────────────────────

type Phase = 'learn' | 'quiz' | 'result';

interface LessonScreenProps {
  lessonId: string;
  progress: AppProgress;
  onBack: () => void;
  onComplete: (lessonId: string, score: number, total: number) => void;
  onToggleFavorite: (cardKey: string) => void;
}

export function LessonScreen({ lessonId, progress, onBack, onComplete, onToggleFavorite }: LessonScreenProps) {
  const lesson = getLessonById(lessonId);
  const [phase, setPhase] = useState<Phase>('learn');
  const [cardIndex, setCardIndex] = useState(0);
  const [quiz, setQuiz] = useState<QuizQuestion[]>([]);
  const [qIndex, setQIndex] = useState(0);
  const [answers, setAnswers] = useState<('correct' | 'wrong')[]>([]);
  const [selected, setSelected] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const [wrongAnim, setWrongAnim] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);
  const [speaking, setSpeaking] = useState(false);

  const handleSpeak = useCallback((text: string) => {
    speak(text);
    setSpeaking(true);
    setTimeout(() => setSpeaking(false), 1200);
  }, []);

  const startQuiz = useCallback(() => {
    const q = buildQuiz(lesson!);
    setQuiz(q);
    setQIndex(0);
    setAnswers([]);
    setSelected(null);
    setScore(0);
    setPhase('quiz');
  }, [lesson]);

  const handleAnswer = useCallback((optIdx: number) => {
    if (selected !== null || !quiz[qIndex]) return;
    const q = quiz[qIndex];
    const isCorrect = optIdx === q.correctIndex;
    setSelected(optIdx);

    if (isCorrect) {
      setScore((s) => s + 1);
      setAnswers((a) => [...a, 'correct']);
      setTimeout(() => speak(quiz[qIndex]?.promptWord ?? quiz[qIndex]?.promptLetter ?? ''), 200);
    } else {
      setWrongAnim(true);
      setAnswers((a) => [...a, 'wrong']);
      setTimeout(() => setWrongAnim(false), 500);
    }

    setTimeout(() => {
      if (qIndex + 1 >= quiz.length) {
        setPhase('result');
        setShowConfetti(true);
      } else {
        setQIndex((i) => i + 1);
        setSelected(null);
      }
    }, 900);
  }, [selected, quiz, qIndex]);

  const handleComplete = useCallback(() => {
    onComplete(lessonId, score, quiz.length);
  }, [lessonId, score, quiz.length, onComplete]);

  if (!lesson) return null;

  const card = lesson.cards[cardIndex];
  const cardKey = `${lessonId}:${card?.id}`;
  const isFav = progress.favorites.includes(cardKey);
  const stars = score >= quiz.length ? 3 : score >= quiz.length - 1 ? 2 : score >= Math.ceil(quiz.length / 2) ? 1 : 0;

  // ── Learn phase ────────────────────────────────────────────────────────────
  if (phase === 'learn') {
    return (
      <Screen>
        <TopBar>
          <BackBtn onClick={onBack}><ArrowLeft size={18} /></BackBtn>
          <LessonTitle>{lesson.title}</LessonTitle>
          <ProgressDots>
            {lesson.cards.map((_, i) => (
              <Dot key={i} active={i === cardIndex} done={i < cardIndex} color={lesson.color} />
            ))}
          </ProgressDots>
        </TopBar>

        <LearnBody>
          <BigEmoji color={lesson.color} onClick={() => handleSpeak(card.word)}>
            {card.emoji}
          </BigEmoji>
          <BigLetter color={lesson.color}>{card.letter}</BigLetter>
          <WordLabel>{card.word}</WordLabel>
          {card.hint && <HintLabel>{card.hint}</HintLabel>}
          <CardActions>
            <ActionBtn
              type="button"
              color="#f59e0b"
              active={speaking}
              title="Ouvir"
              onClick={() => handleSpeak(card.word)}
            >
              <Volume2 size={22} color="#f59e0b" />
            </ActionBtn>
            <ActionBtn
              type="button"
              color="#ef4444"
              active={isFav}
              title={isFav ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}
              onClick={() => onToggleFavorite(cardKey)}
            >
              <Heart size={22} fill={isFav ? '#ef4444' : 'none'} color="#ef4444" />
            </ActionBtn>
          </CardActions>
        </LearnBody>

        <NavRow>
          <NavBtn
            color={lesson.color}
            disabled={cardIndex === 0}
            onClick={() => { if (cardIndex > 0) { setCardIndex((i) => i - 1); } }}
          >
            <ArrowLeft size={18} /> Anterior
          </NavBtn>

          {cardIndex < lesson.cards.length - 1 ? (
            <NavBtn
              color={lesson.color}
              onClick={() => { setCardIndex((i) => i + 1); handleSpeak(lesson.cards[cardIndex + 1].word); }}
            >
              Próxima <ArrowRight size={18} />
            </NavBtn>
          ) : (
            <StartQuizBtn color={lesson.color} onClick={startQuiz}>
              Fazer Quiz 🎯
            </StartQuizBtn>
          )}
        </NavRow>
      </Screen>
    );
  }

  // ── Quiz phase ─────────────────────────────────────────────────────────────
  if (phase === 'quiz') {
    const q = quiz[qIndex];
    if (!q) return null;

    return (
      <Screen>
        <TopBar>
          <BackBtn onClick={onBack}><ArrowLeft size={18} /></BackBtn>
          <LessonTitle>Quiz — {lesson.title}</LessonTitle>
        </TopBar>

        <QuizBody>
          <QuizProgress>
            {quiz.map((_, i) => (
              <QDot
                key={i}
                color={lesson.color}
                state={i < answers.length ? answers[i] : i === qIndex ? 'current' : 'pending'}
              />
            ))}
          </QuizProgress>

          <QuizLabel>{q.label}</QuizLabel>

          <QuizPrompt isShaking={wrongAnim} color={lesson.color}>
            {q.promptEmoji && <PromptEmoji>{q.promptEmoji}</PromptEmoji>}
            {q.promptWord && q.type !== 'word-to-emoji' && <PromptWord>{q.promptWord}</PromptWord>}
            {q.type === 'word-to-emoji' && <PromptLetter color={lesson.color}>{q.promptWord}</PromptLetter>}
            {q.promptLetter && <PromptLetter color={lesson.color}>{q.promptLetter}</PromptLetter>}
          </QuizPrompt>

          <OptionsGrid count={q.options.length}>
            {q.options.map((opt, i) => {
              const state: 'idle' | 'correct' | 'wrong' =
                selected === null
                  ? 'idle'
                  : i === q.correctIndex
                  ? 'correct'
                  : i === selected && selected !== q.correctIndex
                  ? 'wrong'
                  : 'idle';

              return (
                <OptionBtn
                  key={i}
                  state={state}
                  isShaking={state === 'wrong' ? wrongAnim : false}
                  disabled={selected !== null}
                  onClick={() => handleAnswer(i)}
                >
                  {opt.emoji && <OptionEmoji>{opt.emoji}</OptionEmoji>}
                  {opt.letter && <OptionLetter color={lesson.color}>{opt.letter}</OptionLetter>}
                </OptionBtn>
              );
            })}
          </OptionsGrid>

          <FeedbackRow>
            {selected !== null && selected === q.correctIndex && (
              <><CheckCircle size={22} color="#10b981" /> <span style={{ color: '#10b981' }}>Muito bem! 🎉</span></>
            )}
            {selected !== null && selected !== q.correctIndex && (
              <><XCircle size={22} color="#ef4444" /> <span style={{ color: '#ef4444' }}>Era {q.options[q.correctIndex]?.letter ?? q.options[q.correctIndex]?.emoji}!</span></>
            )}
          </FeedbackRow>
        </QuizBody>
      </Screen>
    );
  }

  // ── Result phase ───────────────────────────────────────────────────────────
  const confettiItems = stars > 0
    ? ['⭐', '✨', '🌟', '💫', '⭐', '✨'].map((e, i) => ({
        emoji: e, x: 10 + i * 15, delay: i * 0.15,
      }))
    : [];

  return (
    <Screen>
      <TopBar>
        <BackBtn onClick={onBack}><ArrowLeft size={18} /></BackBtn>
        <LessonTitle>Resultado</LessonTitle>
      </TopBar>

      <ResultBody>
        {showConfetti && confettiItems.map((c, i) => (
          <Confetti key={i} x={c.x} delay={c.delay}>{c.emoji}</Confetti>
        ))}

        <ResultEmoji>
          {stars === 3 ? '🏆' : stars === 2 ? '🎉' : stars === 1 ? '👍' : '😅'}
        </ResultEmoji>

        <ResultTitle color={lesson.color}>
          {stars === 3 ? 'Perfeito!' : stars === 2 ? 'Muito bem!' : stars === 1 ? 'Bom esforço!' : 'Continua a tentar!'}
        </ResultTitle>

        <ResultScore>{score} de {quiz.length} acertos</ResultScore>

        <StarsEarned>
          {[1, 2, 3].map((s) => (
            <span key={s} style={{ opacity: stars >= s ? 1 : 0.2 }}>⭐</span>
          ))}
        </StarsEarned>

        <ContinueBtn color={lesson.color} onClick={handleComplete}>
          Continuar →
        </ContinueBtn>
      </ResultBody>
    </Screen>
  );
}
