// ─── Component ────────────────────────────────────────────────────────────────

interface HomeScreenProps {
  progress: AppProgress;
  speechDebug: SpeechDebugState;
  onSelectLesson: (lessonId: string) => void;
  onOpenFavorites: () => void;
  onSpeechTest: () => void;
}

export function HomeScreen({ progress, speechDebug, onSelectLesson, onOpenFavorites, onSpeechTest }: HomeScreenProps) {
  const totalLessons = LESSONS.length;
  const completedLessons = Object.values(progress.lessons).filter((l) => l.completed).length;
  const progressPct = Math.round((completedLessons / totalLessons) * 100);
  const showSpeechDiagnostics = false;

  return (
    <Page>
      {/* ── Hero ── */}
      <Hero>
        <HeroInner>
          <HeroTop>
            <div>
              <AppName>LêBem</AppName>
              <Tagline>Vamos aprender a ler! 🚀✨</Tagline>
            </div>
            <MascotWrap>🦉</MascotWrap>
          </HeroTop>

          <StatsRow>
            <StatPill color="#f59e0b">
              <StatEmoji>⭐</StatEmoji>
              <StatVal>{progress.totalStars}</StatVal>
              <StatLbl>estrelas</StatLbl>
            </StatPill>
            <StatPill color="#7c3aed">
              <StatEmoji>🏆</StatEmoji>
              <StatVal>Nível {progress.level}</StatVal>
            </StatPill>
            <StatPill color="#10b981">
              <StatEmoji>🔥</StatEmoji>
              <StatVal>{progress.streak}</StatVal>
              <StatLbl>dias</StatLbl>
            </StatPill>
          </StatsRow>

          <ProgressWrap>
            <ProgressFill pct={progressPct} />
          </ProgressWrap>
          <ProgressLabel>
            <span>{completedLessons} de {totalLessons} lições</span>
            <span>{progressPct}% completo</span>
          </ProgressLabel>
        </HeroInner>
      </Hero>

      <Body>
        {/* Temporary speech diagnostics panel. Keep it available in code, but hidden from the main UI. */}
        {showSpeechDiagnostics && (
          <SpeechCard>
            <SpeechHead>
              <div>
                <SpeechTitle>Diagnostico de voz</SpeechTitle>
                <SpeechMeta>
                  {speechDebug.supported ? 'Web Speech API detetada neste browser' : 'Este browser nao suporta speech synthesis'}
                </SpeechMeta>
              </div>
              <SpeechTestButton type="button" onClick={onSpeechTest}>Testar voz</SpeechTestButton>
            </SpeechHead>
            <SpeechGrid>
              <SpeechItem>
                <SpeechKey>Voz preferida</SpeechKey>
                <SpeechValue>{speechDebug.preferredVoiceName ?? 'nenhuma'}</SpeechValue>
              </SpeechItem>
              <SpeechItem>
                <SpeechKey>Idioma</SpeechKey>
                <SpeechValue>{speechDebug.preferredVoiceLang ?? 'n/d'}</SpeechValue>
              </SpeechItem>
              <SpeechItem>
                <SpeechKey>Numero de vozes</SpeechKey>
                <SpeechValue>{speechDebug.voicesCount}</SpeechValue>
              </SpeechItem>
              <SpeechItem>
                <SpeechKey>Ultimo evento</SpeechKey>
                <SpeechValue>{speechDebug.lastEvent}</SpeechValue>
              </SpeechItem>
              <SpeechItem>
                <SpeechKey>A falar</SpeechKey>
                <SpeechValue>{speechDebug.speaking ? 'sim' : 'nao'}</SpeechValue>
              </SpeechItem>
              <SpeechItem>
                <SpeechKey>Em fila</SpeechKey>
                <SpeechValue>{speechDebug.pending ? 'sim' : 'nao'}</SpeechValue>
              </SpeechItem>
              <SpeechItem>
                <SpeechKey>Pausado</SpeechKey>
                <SpeechValue>{speechDebug.paused ? 'sim' : 'nao'}</SpeechValue>
              </SpeechItem>
              <SpeechItem>
                <SpeechKey>Ultimo erro</SpeechKey>
                <SpeechValue>{speechDebug.lastError ?? 'nenhum'}</SpeechValue>
              </SpeechItem>
              <SpeechItem>
                <SpeechKey>Vozes PT</SpeechKey>
                <SpeechValue>
                  {speechDebug.availableVoiceNames.length > 0
                    ? speechDebug.availableVoiceNames.join(', ')
                    : 'nenhuma detetada'}
                </SpeechValue>
              </SpeechItem>
            </SpeechGrid>
          </SpeechCard>
        )}

        {/* ── Favorites CTA ── */}
        <FavCTA onClick={onOpenFavorites}>
          <FavIcon>❤️</FavIcon>
          <FavText>
            <FavTitle>Os meus Favoritos</FavTitle>
            <FavSub>{progress.favorites.length} cartões guardados</FavSub>
          </FavText>
          <FavArrow><ChevronRight size={20} /></FavArrow>
        </FavCTA>

        {/* ── Lesson groups ── */}
        {LESSON_GROUPS.map((group, gi) => {
          const groupLessons = group.ids.map((id) => LESSONS.find((l) => l.id === id)).filter(Boolean) as typeof LESSONS;
          return (
            <GroupSection key={group.label} index={gi}>
              <GroupLabel>{group.label}</GroupLabel>
              <LessonsRow>
                {groupLessons.map((lesson) => {
                  const lp = progress.lessons[lesson.id];
                  const stars = lp?.stars ?? 0;
                  const done  = lp?.completed ?? false;
                  return (
                    <LessonCard
                      key={lesson.id}
                      color={lesson.color}
                      done={done}
                      onClick={() => onSelectLesson(lesson.id)}
                    >
                      <CardTop>
                        <CardEmoji>{lesson.icon}</CardEmoji>
                        {done && <CardBadge color={lesson.color}>✓ Feito</CardBadge>}
                      </CardTop>
                      <CardTitle>{lesson.title}</CardTitle>
                      <CardSub>{lesson.subtitle}</CardSub>
                      <StarsRow>
                        {[1, 2, 3].map((s) => (
                          <StarIcon key={s} lit={stars >= s} color={lesson.color} delay={s * 80}>⭐</StarIcon>
                        ))}
                        <CardCount>{lesson.cards.length} cartões</CardCount>
                      </StarsRow>
                    </LessonCard>
                  );
                })}
              </LessonsRow>
            </GroupSection>
          );
        })}

        {/* ── Badges ── */}
        {progress.badges.length > 0 && (
          <BadgesSection>
            <GroupLabel>🏅 Conquistas</GroupLabel>
            <BadgesGrid>
              {progress.badges.map((badge) => {
                const b = BADGES[badge];
                if (!b) return null;
                return (
                  <BadgeCard key={badge} title={b.desc}>
                    <BadgeEmoji>{b.emoji}</BadgeEmoji>
                    <BadgeName>{b.label}</BadgeName>
                  </BadgeCard>
                );
              })}
            </BadgesGrid>
          </BadgesSection>
        )}
      </Body>
    </Page>
  );
}
